#version 330

#moj_import <minecraft:fog.glsl>
#moj_import <minecraft:globals.glsl>
#moj_import <minecraft:chunksection.glsl>

uniform sampler2D Sampler0;

// Sable water occlusion: depth of the nearest front / back faces of all occlusion volumes.
// The far buffer is rendered mirrored in x (see WaterOcclusionRenderer).
uniform sampler2D SableCloseSampler;
uniform sampler2D SableFarSampler;

in float sphericalVertexDistance;
in float cylindricalVertexDistance;
in vec4 vertexColor;
in vec2 texCoord0;

out vec4 fragColor;

vec4 sampleNearest(sampler2D sampler, vec2 uv, vec2 pixelSize, vec2 du, vec2 dv, vec2 texelScreenSize) {
    // Convert our UV back up to texel coordinates and find out how far over we are from the center of each pixel
    vec2 uvTexelCoords = uv / pixelSize;
    vec2 texelCenter = round(uvTexelCoords) - 0.5f;
    vec2 texelOffset = uvTexelCoords - texelCenter;

    // Move our offset closer to the texel center based on texel size on screen
    texelOffset = (texelOffset - 0.5f) * pixelSize / texelScreenSize + 0.5f;
    texelOffset = clamp(texelOffset, 0.0f, 1.0f);

    uv = (texelCenter + texelOffset) * pixelSize;
    return textureGrad(sampler, uv, du, dv);
}

vec4 sampleNearest(sampler2D source, vec2 uv, vec2 pixelSize) {
    vec2 du = dFdx(uv);
    vec2 dv = dFdy(uv);
    vec2 texelScreenSize = sqrt(du * du + dv * dv);
    return sampleNearest(source, uv, pixelSize, du, dv, texelScreenSize);
}

// Rotated Grid Super-Sampling
vec4 sampleRGSS(sampler2D source, vec2 uv, vec2 pixelSize) {
    vec2 du = dFdx(uv);
    vec2 dv = dFdy(uv);

    vec2 texelScreenSize = sqrt(du * du + dv * dv);
    float maxTexelSize = max(texelScreenSize.x, texelScreenSize.y);

    float minPixelSize = min(pixelSize.x, pixelSize.y);

    float transitionStart = minPixelSize * 1.0;
    float transitionEnd = minPixelSize * 2.0;
    float blendFactor = smoothstep(transitionStart, transitionEnd, maxTexelSize);

    float duLength = length(du);
    float dvLength = length(dv);
    float minDerivative = min(duLength, dvLength);
    float maxDerivative = max(duLength, dvLength);

    float effectiveDerivative = sqrt(minDerivative * maxDerivative);

    float mipLevelExact = max(0.0, log2(effectiveDerivative / minPixelSize));

    float mipLevelLow = floor(mipLevelExact);
    float mipLevelHigh = mipLevelLow + 1.0;
    float mipBlend = fract(mipLevelExact);

    const vec2 offsets[4] = vec2[](
    vec2(0.125, 0.375),
    vec2(-0.125, -0.375),
    vec2(0.375, -0.125),
    vec2(-0.375, 0.125)
    );

    vec4 rgssColorLow = vec4(0.0);
    vec4 rgssColorHigh = vec4(0.0);
    for (int i = 0; i < 4; ++i) {
        vec2 sampleUV = uv + offsets[i] * pixelSize;
        rgssColorLow += textureLod(source, sampleUV, mipLevelLow);
        rgssColorHigh += textureLod(source, sampleUV, mipLevelHigh);
    }
    rgssColorLow *= 0.25;
    rgssColorHigh *= 0.25;

    vec4 rgssColor = mix(rgssColorLow, rgssColorHigh, mipBlend);

    vec4 nearestColor = sampleNearest(source, uv, pixelSize, du, dv, texelScreenSize);

    return mix(nearestColor, rgssColor, blendFactor);
}

void main() {
    vec2 sableUv = gl_FragCoord.xy / vec2(textureSize(SableCloseSampler, 0));
    float sableCloseDepth = texture(SableCloseSampler, sableUv).r;
    float sableFarDepth = texture(SableFarSampler, vec2(1.0 - sableUv.x, sableUv.y)).r;
    if (gl_FragCoord.z > sableCloseDepth && gl_FragCoord.z < sableFarDepth) {
        discard;
    }

    vec4 color = (UseRgss == 1 ? sampleRGSS(Sampler0, texCoord0, 1.0f / TextureSize) : sampleNearest(Sampler0, texCoord0, 1.0f / TextureSize)) * vertexColor;
    color = mix(FogColor * vec4(1, 1, 1, color.a), color, ChunkVisibility);
#ifdef ALPHA_CUTOUT
    if (color.a < ALPHA_CUTOUT) {
        discard;
    }
#endif
    fragColor = apply_fog(color, sphericalVertexDistance, cylindricalVertexDistance, FogEnvironmentalStart, FogEnvironmentalEnd, FogRenderDistanceStart, FogRenderDistanceEnd, FogColor);
}
package dev.ryanhcode.sable.mixin.water_occlusion;

import com.llamalad7.mixinextras.injector.ModifyReturnValue;
import dev.ryanhcode.sable.mixinterface.water_occlusion.CameraWaterOcclusionExtension;
import dev.ryanhcode.sable.sublevel.water_occlusion.WaterOcclusionContainer;
import net.minecraft.client.Camera;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.material.FogType;
import net.minecraft.world.phys.Vec3;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;

@Mixin(Camera.class)
public class CameraMixin implements CameraWaterOcclusionExtension {

    @Shadow
    private Vec3 position;

    @Shadow
    private Level level;

    @Unique
    private boolean sable$ignoreOcclusion = false;

    @ModifyReturnValue(method = "getFluidInCamera", at = @At("RETURN"))
    public FogType sable$getFluidInCamera(final FogType original) {
        if (this.sable$ignoreOcclusion) {
            return original;
        }

        if (original == FogType.WATER || original == FogType.LAVA) {
            final boolean occluded = this.sable$isOccluded();

            if (occluded) {
                return FogType.NONE;
            }
        }

        return original;
    }

    @Override
    public void sable$setIgnoreOcclusion(final boolean ignore) {
        this.sable$ignoreOcclusion = ignore;
    }

    @Override
    public boolean sable$isIgnoreOcclusion() {
        return this.sable$ignoreOcclusion;
    }

    @Override
    public boolean sable$isOccluded() {
        final WaterOcclusionContainer<?> container = WaterOcclusionContainer.getContainer(this.level);

        if (container == null)
            return false;

        return container.isOccluded(this.position);
    }
}
package dev.ryanhcode.sable.mixin.water_occlusion;

import com.llamalad7.mixinextras.injector.wrapoperation.Operation;
import com.llamalad7.mixinextras.injector.wrapoperation.WrapOperation;
import com.mojang.blaze3d.pipeline.RenderPipeline;
import com.mojang.blaze3d.systems.RenderPass;
import com.mojang.blaze3d.textures.GpuSampler;
import dev.ryanhcode.sable.SableClient;
import dev.ryanhcode.sable.render.sky_light_shadow.SableSkyLightShadows;
import dev.ryanhcode.sable.render.water_occlusion.WaterOcclusionRenderer;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.client.renderer.chunk.ChunkSectionLayerGroup;
import net.minecraft.client.renderer.chunk.ChunkSectionsToRender;
import dev.ryanhcode.sable.veillite.api.compat.SodiumCompat;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

@Mixin(ChunkSectionsToRender.class)
public class ChunkSectionsToRenderMixin {

    /**
     * Renders the sky light shadow map right before the first layer group, and the water occlusion buffers right
     * before the translucent layer, while no render pass is open
     */
    @Inject(method = "renderGroup", at = @At("HEAD"))
    private void sable$preRenderGroup(final ChunkSectionLayerGroup group, final GpuSampler sampler, final CallbackInfo ci) {
        if (SodiumCompat.isLoaded()) {
            return; // Sodium cancels renderGroup; its draw hook does this instead
        }

        if (group == ChunkSectionLayerGroup.OPAQUE) {
            SableSkyLightShadows.renderShadowMap();
        } else if (group == ChunkSectionLayerGroup.TRANSLUCENT) {
            SableClient.WATER_OCCLUSION_RENDERER.preRenderTranslucent();
        }
    }

    /**
     * Swaps in the occluded translucent terrain pipeline, which discards water inside occlusion volumes, and the
     * shadowed terrain pipelines, which darken the sky light below sub-levels
     */
    @WrapOperation(method = "renderGroup", at = @At(value = "INVOKE", target = "Lcom/mojang/blaze3d/systems/RenderPass;setPipeline(Lcom/mojang/blaze3d/pipeline/RenderPipeline;)V"))
    private void sable$setTranslucentPipeline(final RenderPass renderPass, final RenderPipeline pipeline, final Operation<Void> original) {
        final WaterOcclusionRenderer renderer = SableClient.WATER_OCCLUSION_RENDERER;

        final boolean occluded = pipeline == RenderPipelines.TRANSLUCENT_TERRAIN && renderer.isActive();
        final RenderPipeline base = occluded ? WaterOcclusionRenderer.TRANSLUCENT_TERRAIN_OCCLUDED : pipeline;
        final RenderPipeline swapped = SableSkyLightShadows.isActive() ? SableSkyLightShadows.getShadowedPipeline(base) : base;

        original.call(renderPass, swapped);
        if (occluded) {
            renderer.bindSamplers(renderPass);
        }
        if (swapped != base) {
            SableSkyLightShadows.bind(renderPass);
        }
    }
}

