package dev.mcf.e2e.mixin;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Pseudo;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

import java.util.concurrent.atomic.AtomicInteger;

/**
 * Counts Sodium section mesh uploads: Sodium restarts a section's fade-in on every upload further than ~28 blocks
 * from the camera (-1 = no fade). Only applied when Sodium is loaded ({@code mcf_e2e.sodium.mixins.json}).
 */
@Pseudo
@Mixin(targets = "net.caffeinemc.mods.sodium.client.render.chunk.RenderSection", remap = false)
public class SodiumFadeProbeMixin {
    public static final AtomicInteger UPLOADS = new AtomicInteger();
    public static final AtomicInteger FADING_UPLOADS = new AtomicInteger();

    @Inject(method = "setFadeTime(I)V", at = @At("HEAD"), require = 0)
    private void mcf$countFade(final int fadeTime, final CallbackInfo ci) {
        UPLOADS.incrementAndGet();
        if (fadeTime != -1) {
            FADING_UPLOADS.incrementAndGet();
        }
    }
}
